import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"開發手冊","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/dev-guide/index.md","filePath":"zh-HK/dev-guide/index.md","lastUpdated":1785993908000}'),s={name:"zh-HK/dev-guide/index.md"};function i(n,e,l,d,c,g){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="開發手冊" tabindex="-1">開發手冊 <a class="header-anchor" href="#開發手冊" aria-label="Permalink to &quot;開發手冊&quot;">​</a></h1><p>Lertaro 提供了一套開放的插件 SDK(<code>Lertaro.PluginSdk</code>)，第三方程式集可以引用它來擴展搜尋行為、添加右鍵選單動作、與其他視窗集成，以及自訂介面。本手冊記錄了這套 SDK 的全部內容。</p><ul><li><strong><a href="./architecture.html">架構設計</a></strong> —— App、後臺 Service 與插件之間是如何配合的。</li><li><strong><a href="./getting-started.html">快速上手</a></strong> —— 搭建一個插件項目並加載它。</li><li><strong>插件 SDK 參考</strong>: <ul><li><strong><a href="./sdk/core-search-actions.html">核心檢索與動作</a></strong> —— 貢獻搜尋結果與結果動作。</li><li><strong><a href="./sdk/system-adapters.html">系統與對話方塊適配</a></strong> —— 與檔案總管、原生檔案對話方塊及其他前臺視窗集成。</li><li><strong><a href="./sdk/ui-extensions.html">介面與預覽擴展</a></strong> —— 側欄過濾器、結果列、檔案預覽、縮略圖、主題與語言包。</li><li><strong><a href="./sdk/abstractions.html">共享抽象契約</a></strong> —— 插件收到的只讀模型(<code>ISearchResult</code>、 <code>IPluginSearchWindow</code>)以及配置模式(<code>IConfigurable</code>)。</li><li><strong><a href="./sdk/services.html">宿主服務</a></strong> —— 宿主暴露給插件的靜態服務(圖示、收藏夾、歷史記錄、檔案中繼資料、目錄索引、插件專屬設定、日誌)。</li></ul></li><li><strong><a href="./examples.html">插件示例</a></strong> —— 兩個真實隨附插件的案例分析。</li><li><strong><a href="./packaging.html">打包與發佈</a></strong> —— 編譯好的插件 DLL 是如何被發現並加載的。</li></ul><p>本手冊裏的每一個接口簽名都直接對照當前 <code>PluginSdk</code> 源碼核實過——如果發現和文檔有出入，以代碼為準。</p>',4)])])}const p=t(s,[["render",i]]);export{m as __pageData,p as default};
